function latestRecipients($tid){global $db;$eid=(int)ssQuery($db,'SELECT MAX(id) FROM support_events WHERE ticket_id=?',[$tid])->fetchColumn();$ids=array_map('intval',ssQuery($db,'SELECT recipient_id FROM support_outbox WHERE event_key=? ORDER BY recipient_id',['ticket:'.$eid])->fetchAll(PDO::FETCH_COLUMN));return $ids;}
$mailTicket=cmd(3,'support_create',['module'=>'website','body'=>'Check email routing'])['id'];ok(latestRecipients($mailTicket)===[1,3],'receipt and website owner recipients');
update(1,$mailTicket,'acknowledge',['next_update_at'=>$due]);ok(latestRecipients($mailTicket)===[3],'acknowledgement recipient');
cmd(3,'support_reply',['id'=>$mailTicket,'version'=>ticket($mailTicket)['version'],'body'=>'More details']);ok(latestRecipients($mailTicket)===[1],'reply goes to assigned handler');
update(1,$mailTicket,'assign',['owner_id'=>2]);ok(latestRecipients($mailTicket)===[2,3],'new owner and requester notified');
update(2,$mailTicket,'status',['status'=>'resolved']);ok(latestRecipients($mailTicket)===[3],'resolution to requester');
update(3,$mailTicket,'status',['status'=>'closed']);ok(latestRecipients($mailTicket)===[2],'confirmation to handler');
